import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Fake pricing gateway: unit prices in euros, per sku.
const prices = { A: 10, B: 25.5, C: 0.1, D: 33.33, E: 101, F: 100, G: 0.01 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const totalOf = async (items) => (await (await post({ items })).json()).total

test('POST /orders 201 returns id, items and total; headers are JSON', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 20)
})

test('POST /orders ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across lines', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('no discount at or below 100 (threshold is strictly > 100)', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount applies to the whole order above 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalOf([{ sku: 'A', qty: 20 }]), 180)
})

test('CHARACTERIZATION: current behaviour may be unintended — discount cliff: an order of 101 costs less than one of 100', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 90) // 101 -> 90.9 -> 90
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 100)
})

test('CHARACTERIZATION: current behaviour may be unintended — total is floored to whole euros, cents are dropped (also after discount)', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 1 }]), 25) // 25.5 -> 25
  assert.equal(await totalOf([{ sku: 'G', qty: 10100 }]), 90) // 101 -> 90.9 -> 90
  assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 133 - 13) // 133.32 -> 119.988 -> 119
})

test('CHARACTERIZATION: current behaviour may be unintended — floating-point sums floored (0.1 * 3 = 0.30000000000000004)', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 0)
  assert.equal(await totalOf([{ sku: 'C', qty: 1010 }]), 90) // 101.00000000000001 -> 90.9
})

test('CHARACTERIZATION: current behaviour may be unintended — unknown sku / missing qty yield total null (NaN serialised), order still 201', async () => {
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
  assert.equal(await totalOf([{ sku: 'A' }]), null)
})

test('CHARACTERIZATION: current behaviour may be unintended — negative qty gives a negative total', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: -1 }]), -10)
})

test('POST /orders 400 when items missing, empty, not an array, or body invalid JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{bad')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('CHARACTERIZATION: current behaviour may be unintended — unknown order id returns 200 with { error } instead of 404', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unrouted requests return 404 { error: "no route" }', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
